use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::aap::caps::state_rw;
use crate::wasi::clocks::wall_clock;

struct Node;

/// Key under which every call records the input it received.
const LAST_INPUT_KEY: &str = "last-input";

/// How many times to offer the notification before giving up.
const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Record this call's input in the shared store.
        state_rw::put(LAST_INPUT_KEY, &feed_url);

        // Read the time.
        let seconds = wall_clock::now().seconds;

        // One permitted fetch. A transport failure is a value (counted as zero
        // characters); a host outside the allowlist traps at the boundary.
        let fetched: u32 = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Notify the digest channel. The contract requires `notified == true`
        // on every output, so a report claiming otherwise is never produced:
        // retry a bounded number of times, then trap rather than violate it.
        let message = format!(
            "heartbeat at {}: fetched {} characters from {}",
            seconds, fetched, feed_url
        );
        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }
        if !notified {
            panic!("notification was not accepted by the digest channel");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
